package org.eclipse.rdf4j.sail.lmdb;

/** A source-derived selective-access ceiling; this measures neither pages nor total CPU/work. */
record NativeStatementAccessBudget(long followsRows) {
	NativeStatementAccessBudget {
		if (followsRows <= 0L || followsRows == Long.MAX_VALUE) {
			throw new IllegalArgumentException("A positive finite follows census is required");
		}
	}

	enum Decision {
		SELECTIVE,
		BROAD,
		UNKNOWN
	}

	record Evidence(boolean complete, long requests, long scanned, long closed, long countRequests,
			long unknownScans, long failedRequests, long broadFollowsRows) {
		Evidence {
			if ((requests | scanned | closed | countRequests | unknownScans | failedRequests | broadFollowsRows) < 0L) {
				throw new IllegalArgumentException("Unknown counters must be explicit, never negative quantities");
			}
		}

		boolean known() {
			return complete && countRequests == 0L && unknownScans == 0L && failedRequests == 0L && closed == requests;
		}

		long work() {
			return Math.addExact(requests, scanned);
		}
	}

	long exclusiveBound() {
		return followsRows + 1L;
	}

	Decision assess(Evidence evidence) {
		return !evidence.known() ? Decision.UNKNOWN
				: evidence.work() < exclusiveBound() ? Decision.SELECTIVE : Decision.BROAD;
	}
}
